'use client';

import { useEffect, useId, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import './team-grid.css';

export interface TeamGridItem {
  id: string;
  name: string;
  role: string;
  bio: string;
  portrait: ReactNode;
  links?: { label: string; href: string }[];
}

export interface TeamGridProps {
  items: TeamGridItem[];
  title?: string;
  className?: string;
}

/** Portrait cards with a full, keyboard-accessible profile for each person. */
export function TeamGrid({ items, title = 'Good people. Different perspectives.', className = '' }: TeamGridProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selected = items.find(item => item.id === selectedId);
  const isOpen = Boolean(selected);
  const viewer = useRef<HTMLDialogElement>(null);
  const opener = useRef<HTMLButtonElement | null>(null);
  const instance = useId();
  const titleId = `ac-team-title-${instance}`;
  const profileId = `ac-team-profile-${instance}`;
  const profileTitleId = `${profileId}-title`;

  useEffect(() => {
    if (!isOpen) return;
    const modal = viewer.current;
    if (!modal) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    if (!modal.open) modal.showModal();
    return () => {
      if (modal.open) modal.close();
      document.body.style.overflow = previousOverflow;
      opener.current?.focus({ preventScroll: true });
    };
  }, [isOpen]);

  return (
    <section className={`ac-team-grid ${className}`.trim()} aria-labelledby={title ? titleId : undefined} aria-label={title ? undefined : 'Our team'}>
      {title && <header className="ac-team-grid-heading"><span>THE PEOPLE BEHIND THE WORK</span><h2 id={titleId}>{title}</h2></header>}
      {items.length ? <div className="ac-team-grid-cards">{items.map((person, index) => <article className="ac-team-grid-card" key={person.id}>
        <div className="ac-team-grid-portrait" aria-hidden="true" ref={element => { if (element) element.inert = true; }}>{person.portrait}<span className="ac-team-grid-number">{String(index + 1).padStart(2, '0')}</span></div>
        <div className="ac-team-grid-person"><h3>{person.name}</h3><span>{person.role}</span></div>
        <p className="ac-team-grid-preview">{person.bio}</p>
        <button type="button" className="ac-team-grid-meet" aria-haspopup="dialog" aria-controls={profileId} aria-expanded={selectedId === person.id && isOpen} onClick={event => { opener.current = event.currentTarget; setSelectedId(person.id); }}>Meet {person.name}<span aria-hidden="true">↗</span></button>
      </article>)}</div> : <p className="ac-team-grid-empty">Team profiles will appear here.</p>}
      <dialog ref={viewer} id={profileId} className="ac-team-grid-dialog" aria-labelledby={profileTitleId} onCancel={event => { event.preventDefault(); setSelectedId(null); }} onClose={() => { if (!viewer.current?.open) setSelectedId(null); }}>
        <header><span>MEET THE TEAM</span><button className="ac-team-grid-close" type="button" onClick={() => setSelectedId(null)}>Close <span aria-hidden="true">×</span></button></header>
        {selected && <div className="ac-team-grid-profile"><div className="ac-team-grid-profile-portrait" aria-hidden="true" ref={element => { if (element) element.inert = true; }}>{selected.portrait}</div><div className="ac-team-grid-profile-copy"><span className="ac-team-grid-profile-role">{selected.role}</span><h2 id={profileTitleId}>{selected.name}</h2><p>{selected.bio}</p>{Boolean(selected.links?.length) && <nav aria-label={`${selected.name} links`} className="ac-team-grid-links">{selected.links?.map((link, index) => <a key={`${link.href}-${index}`} href={link.href}>{link.label}<span aria-hidden="true">↗</span></a>)}</nav>}</div></div>}
      </dialog>
    </section>
  );
}

.ac-team-grid {
  --ac-team-surface: #edece6;
  --ac-team-ink: #303a30;
  --ac-team-muted: #697366;
  --ac-team-line: #303a3030;
  --ac-team-accent: #48623d;
  container-type: inline-size;
  padding: 32px;
  background: var(--ac-team-surface);
  color: var(--ac-team-ink);
  font-family: inherit;
}
.ac-team-grid, .ac-team-grid::before, .ac-team-grid::after, .ac-team-grid *, .ac-team-grid *::before, .ac-team-grid *::after { box-sizing: border-box; }
.ac-team-grid button, .ac-team-grid a { color: inherit; font: inherit; }
.ac-team-grid button { cursor: pointer; }
.ac-team-grid :is(button, a):focus-visible { outline: 2px solid var(--ac-team-accent); outline-offset: 4px; }
.ac-team-grid-heading { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 32px; }
.ac-team-grid-heading > span { font-size: 10px; letter-spacing: .1em; color: var(--ac-team-muted); }
.ac-team-grid-heading h2 { max-width: 15ch; margin: 0; font-size: clamp(28px, 5cqw, 52px); font-weight: 500; line-height: 1.04; letter-spacing: -.045em; }
.ac-team-grid-cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
.ac-team-grid-card { min-width: 0; display: flex; flex-direction: column; }
.ac-team-grid-portrait { position: relative; overflow: hidden; aspect-ratio: 4/4.5; background: #d0d5c8; }
.ac-team-grid-portrait > :not(.ac-team-grid-number) { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform .4s cubic-bezier(.2,.7,.2,1); }
.ac-team-grid-card:hover .ac-team-grid-portrait > :not(.ac-team-grid-number) { transform: scale(1.035); }
.ac-team-grid-number { position: absolute; top: 12px; left: 12px; font-size: 11px; color: #fff; mix-blend-mode: difference; }
.ac-team-grid-person { margin-top: 17px; }
.ac-team-grid-person h3 { margin: 0 0 6px; font-size: clamp(19px, 2.5cqw, 28px); font-weight: 500; letter-spacing: -.035em; }
.ac-team-grid-person > span { font-size: 12px; color: var(--ac-team-muted); }
.ac-team-grid-preview { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin: 16px 0; font-size: 13px; line-height: 1.6; color: var(--ac-team-muted); }
.ac-team-grid-meet { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 44px; width: 100%; margin-top: auto; padding: 10px 0; border: 0; border-top: 1px solid var(--ac-team-line); background: transparent; text-align: left; font-size: 12px!important; }
.ac-team-grid-meet > span { font-size: 21px; transition: transform .2s; }
.ac-team-grid-meet:hover > span { transform: translate(2px, -2px); }
.ac-team-grid-empty { display: grid; place-items: center; min-height: 250px; color: var(--ac-team-muted); }
.ac-team-grid-dialog { width: min(850px, calc(100vw - 28px)); max-width: none; max-height: 90dvh; padding: 25px; background: var(--ac-team-surface); color: var(--ac-team-ink); border: 1px solid var(--ac-team-line); font-family: inherit; overflow: auto; }
.ac-team-grid-dialog:not([open]) { display: none; }
.ac-team-grid-dialog::backdrop { background: #172119bf; backdrop-filter: blur(5px); }
.ac-team-grid-dialog > header { display: flex; justify-content: space-between; align-items: center; gap: 20px; padding-bottom: 20px; font-size: 10px; letter-spacing: .1em; }
.ac-team-grid-close { display: flex; align-items: center; gap: 15px; min-height: 44px; padding: 6px 10px; border: 0; background: transparent; font-size: 13px!important; letter-spacing: 0; }
.ac-team-grid-close > span { font-size: 28px; line-height: 1; }
.ac-team-grid-profile { display: grid; grid-template-columns: minmax(0, .85fr) minmax(0, 1fr); align-items: start; gap: 35px; }
.ac-team-grid-profile-portrait { aspect-ratio: 4/5; overflow: hidden; background: #d0d5c8; }
.ac-team-grid-profile-portrait > * { display: block; width: 100%; height: 100%; object-fit: cover; }
.ac-team-grid-profile-copy { padding: 15px 0; }
.ac-team-grid-profile-role { color: var(--ac-team-muted); font-size: 12px; }
.ac-team-grid-profile h2 { margin: 12px 0 22px; font-size: clamp(34px, 4vw, 54px); letter-spacing: -.05em; line-height: 1.05; font-weight: 500; }
.ac-team-grid-profile p { margin: 0; font-size: 15px; line-height: 1.8; white-space: pre-line; }
.ac-team-grid-links { display: flex; flex-wrap: wrap; gap: 15px 25px; margin-top: 25px; }
.ac-team-grid-links a { display: flex; align-items: center; gap: 13px; min-height: 44px; font-size: 13px; text-underline-offset: 5px; }
@container (max-width: 720px) {
  .ac-team-grid-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ac-team-grid-heading { align-items: start; flex-direction: column; gap: 12px; }
}
@container (max-width: 430px) {
  .ac-team-grid-cards { grid-template-columns: minmax(0, 1fr); }
  .ac-team-grid-portrait { aspect-ratio: 5/4; }
  .ac-team-grid-heading h2 { font-size: 35px; }
}
@media (max-width: 600px) {
  .ac-team-grid-dialog { padding: 18px; }
  .ac-team-grid-profile { grid-template-columns: 1fr; gap: 15px; }
  .ac-team-grid-profile-portrait { width: min(100%, 260px); aspect-ratio: 5/4; }
  .ac-team-grid-profile p { font-size: 14px; }
}
@media (prefers-reduced-motion: reduce) {
  .ac-team-grid-portrait > :not(.ac-team-grid-number), .ac-team-grid-meet > span { transition: none; }
  .ac-team-grid-card:hover .ac-team-grid-portrait > :not(.ac-team-grid-number), .ac-team-grid-meet:hover > span { transform: none; }
}
